// ── PREPARE CONTEXT ──────────────────────────────────────────────────────────
// Merges Telegram trigger data + Postgres student profile into a single
// enriched context object that all downstream nodes can reference.

const triggerData = $('Telegram Trigger').item.json;
const dbRow       = $input.item.json;

// ── Basic identifiers ────────────────────────────────────────────────────────
const messageText = triggerData.message?.text || '';
const studentId   = String(triggerData.message?.from?.id   || '');
const studentName = triggerData.message?.from?.first_name  || 'Student';
const chatId      = triggerData.message?.chat?.id;

// ── Student state from Postgres ──────────────────────────────────────────────
const attemptCount  = parseInt(dbRow.attempt_count)  || 0;
const masteryScore  = parseInt(dbRow.mastery_score)  || 0;
const currentTopic  = dbRow.current_topic            || 'Earth Science Basics';
const misconceptions = dbRow.misconceptions          || '[]';

// ── Intent classification (keyword-based — fast, free, reliable) ─────────────
const lower = messageText.toLowerCase().trim();
let intent  = 'answer_attempt'; // default

if (/^(hi|hello|hey|selamat|good morning|good afternoon|halo|hy)\b/i.test(lower)) {
  intent = 'greeting';
} else if (
  lower.endsWith('?') ||
  /^(what|how|why|when|where|who|is |are |can |does |could |would )/.test(lower)
) {
  intent = 'new_question';
} else if (
  /(clarify|what do you mean|i don.t understand|explain that|elaborate|confused|maksud)/i.test(lower)
) {
  intent = 'clarification';
} else if (
  /(give up|just tell me|i give up|answer please|tell me the answer|just give|langsung kasih|jawab saja|kasih tau)/i.test(lower)
) {
  intent = 'bypass_attempt';
}

// ── Socratic response mode (driven by attempt count) ─────────────────────────
//   0–4   → ask only guiding questions, never confirm or deny
//   5–9   → give directional hints
//   10–14 → explain the concept, ask student to apply it
//   15–19 → partial answer + ask student to complete
//   20    → release full answer, reset counter
let responseMode;
if      (attemptCount <  5)  responseMode = 'socratic_question';
else if (attemptCount < 10)  responseMode = 'hint';
else if (attemptCount < 15)  responseMode = 'explain_concept';
else if (attemptCount < 20)  responseMode = 'partial_answer';
else                         responseMode = 'full_answer';

// ── Misconception detection (Earth Science / Geography / Disasters) ───────────
const misconceptionPatterns = [
  {
    pattern: /epicenter.*caus|caus.*epicenter/i,
    type: 'epicenter_confusion',
    correction: 'The epicenter is the surface point above the focus. The energy originates at the focus (hypocenter) underground, not the epicenter.'
  },
  {
    pattern: /all earthquake.*tsunami|earthquake always.*tsunami/i,
    type: 'earthquake_tsunami_assumption',
    correction: 'Only submarine earthquakes that produce large vertical seafloor displacement generate tsunamis.'
  },
  {
    pattern: /volcano.*random|random.*volcano/i,
    type: 'volcano_distribution',
    correction: 'Volcanoes are not randomly distributed. They follow tectonic plate boundaries and hotspots.'
  },
  {
    pattern: /richter scale (is |are )?use/i,
    type: 'richter_outdated',
    correction: 'The Richter scale is largely obsolete for large earthquakes. Scientists now use the Moment Magnitude Scale (Mw).'
  },
  {
    pattern: /desert.*always hot|all desert.*hot/i,
    type: 'desert_temperature',
    correction: 'Deserts are defined by low precipitation (<250 mm/yr), not temperature. Antarctica and the Gobi are cold deserts.'
  },
  {
    pattern: /magma.*same.*lava|lava.*same.*magma|magma and lava (is|are) same/i,
    type: 'magma_lava_confusion',
    correction: 'Magma is molten rock underground. Lava is the same material after it erupts onto the surface.'
  },
  {
    pattern: /tsunami.*wind|wind.*cause.*tsunami/i,
    type: 'tsunami_wind_cause',
    correction: 'Tsunamis are caused by sudden displacement of large volumes of water (earthquakes, landslides, volcanic eruptions) — not wind.'
  },
];

let detectedMisconception = null;
for (const mp of misconceptionPatterns) {
  if (mp.pattern.test(messageText)) {
    detectedMisconception = JSON.stringify(mp);
    break;
  }
}

// ── Difficulty calibration from mastery ──────────────────────────────────────
//   mastery 0 → difficulty 1 (observation)
//   mastery 5 → difficulty 5 (evaluation)
const difficultyLevel = Math.min(masteryScore + 1, 5);

return [{
  json: {
    // Identifiers
    studentId,
    studentName,
    chatId,
    messageText,
    // Classification
    intent,
    bypassAttempt: intent === 'bypass_attempt',
    // Adaptive state
    attemptCount,
    masteryScore,
    currentTopic,
    misconceptions,
    responseMode,
    difficultyLevel,
    isFullAnswerMode: responseMode === 'full_answer',
    // Misconception
    detectedMisconception,
  }
}];

// ── GUARDRAIL GATE ────────────────────────────────────────────────────────────
// 1. Anti-spoiler check: block answer reveals before the threshold
// 2. Mastery leveling: detect success signals, increment mastery_score
// 3. Attempt management: increment counter or reset on full_answer
// 4. Misconception logging: append newly detected misconceptions to student record

const agentOutput = $('Orchestrator Agent').item.json.output || '';
const ctx = $('Prepare Context').item.json;

const {
  attemptCount, responseMode, bypassAttempt,
  studentName, masteryScore, studentId,
  currentTopic, misconceptions, chatId,
  detectedMisconception
} = ctx;

// ── Anti-spoiler patterns ─────────────────────────────────────────────────────
// These fire only when the mode does NOT allow a full answer yet.
const spoilerPatterns = [
  /the (?:correct |right )?answer is\s+[^.!?\n]{5,}/i,
  /it(?:'s| is)(?: called)? (?:the )?[A-Z][a-z]{3,}[\s,]/,
  /(?:correct|right|exactly)!\s+[A-Z][a-z]+ (?:is|are) /i,
  /the definition (?:is|of [\w ]+ is)\s+[^.!?\n]{10,}/i,
];

let isSafe = true;
if (responseMode !== 'full_answer') {
  for (const p of spoilerPatterns) {
    if (p.test(agentOutput)) { isSafe = false; break; }
  }
}

// ── Final response (replace if guardrail fired) ───────────────────────────────
const finalResponse = isSafe
  ? agentOutput
  : `💪 Semangat, ${studentName}! Let me keep guiding you rather than jumping to the answer.

🔍 Here is a clue: look back at what you already know about this topic. What single fact might unlock the next step for you?

*(Attempt ${attemptCount} of 20)*`;

// ── Mastery leveling ─────────────────────────────────────────────────────────
// Detect genuine praise/confirmation in agent output
const successSignals = /\b(correct|well done|excellent|spot on|exactly right|bravo|great answer|nicely done|perfect|bagus|tepat|benar)\b/i;
const shouldLevelUp = successSignals.test(agentOutput) && responseMode !== 'full_answer';

// ── Attempt counter management ────────────────────────────────────────────────
// Reset to 0 after full answer delivered; increment otherwise
const newAttemptCount = responseMode === 'full_answer' ? 0 : attemptCount + 1;
const newMasteryScore = shouldLevelUp ? Math.min(masteryScore + 1, 5) : masteryScore;

// ── Misconception logging ─────────────────────────────────────────────────────
let updatedMisconceptions = misconceptions;
if (detectedMisconception) {
  try {
    const arr    = typeof misconceptions === 'string' ? JSON.parse(misconceptions) : misconceptions;
    const parsed = JSON.parse(detectedMisconception);
    // Avoid duplicates
    if (!arr.find(m => m.type === parsed.type)) {
      arr.push({ type: parsed.type, firstSeenAt: new Date().toISOString() });
    }
    updatedMisconceptions = JSON.stringify(arr);
  } catch (e) {
    updatedMisconceptions = misconceptions; // safe fallback
  }
}

return [{
  json: {
    studentId,
    studentName,
    chatId,
    currentTopic,
    finalResponse,
    isSafe,
    newAttemptCount,
    newMasteryScore,
    updatedMisconceptions,
    shouldLevelUp,
  }
}];
